package com.dentalclinic.treatment;
import com.dentalclinic.treatment.service.*;import com.dentalclinic.treatment.controller.*;import com.dentalclinic.treatment.dto.*;import com.dentalclinic.treatment.entity.*;
import com.dentalclinic.clinic.entity.Clinic;import com.dentalclinic.user.entity.AppUser;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.access.AccessDeniedException;import java.util.*;import java.util.concurrent.*;import java.math.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"spring.jpa.show-sql=false"})
@EnabledIfEnvironmentVariable(named="TREATMENT_ITEM_TEST_DATABASE",matches="true")
class TreatmentPlanItemDatabaseTest {
 @Autowired JdbcTemplate jdbc;@Autowired TreatmentPlanService plans;@Autowired TreatmentPlanItemService entries;@Autowired TreatmentPlanItemController controller;@Autowired PlatformTransactionManager transactions;
 UUID clinic,user,patient,doctor,appointment,consultation,parent;AppUser actor;
 @BeforeEach void fixture(){assertTrue(jdbc.queryForObject("select current_database()",String.class).startsWith("dental_clinic_v19_verification_"));clinic=UUID.randomUUID();user=UUID.randomUUID();patient=UUID.randomUUID();doctor=UUID.randomUUID();appointment=UUID.randomUUID();consultation=UUID.randomUUID();parent=UUID.randomUUID();
 jdbc.update("insert into clinic(id,clinic_code,clinic_name) values (?,?,?)",clinic,clinic.toString(),"Test clinic");
 jdbc.update("insert into app_user(id,clinic_id,first_name) values (?,?,?)",user,clinic,"Test actor");
 jdbc.update("insert into patient(id,clinic_id,patient_number,first_name,gender,phone) values (?,?,?,'Patient','OTHER','123')",patient,clinic,patient.toString());
 jdbc.update("insert into doctor_profile(id,clinic_id,user_id) values (?,?,?)",doctor,clinic,user);
 jdbc.update("insert into appointment(id,clinic_id,appointment_number,patient_id,doctor_id,appointment_date,start_time,end_time) values (?,?,?,?,?,current_date,'09:00','09:30')",appointment,clinic,appointment.toString(),patient,doctor);
 jdbc.update("insert into consultation(id,clinic_id,appointment_id,patient_id,doctor_id) values (?,?,?,?,?)",consultation,clinic,appointment,patient,doctor);
 jdbc.update("insert into case_sheet(id,clinic_id,consultation_id,appointment_id,patient_id,doctor_id,case_sheet_number,chief_complaint) values (?,?,?,?,?,?,?,'Pain')",parent,clinic,consultation,appointment,patient,doctor,parent.toString());
 actor=AppUser.builder().id(user).clinic(Clinic.builder().id(clinic).active(true).build()).build();login();}
 void login(String... permissions){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(actor,null,Arrays.stream(permissions).map(SimpleGrantedAuthority::new).toList()));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}

 TreatmentPlanResponse plan(){var r=new CreateTreatmentPlanRequest();r.setClinicId(clinic);r.setCaseSheetId(parent);return plans.createTreatmentPlan(r);}
 TreatmentPlanItemResponse item(UUID plan){UUID procedure=UUID.randomUUID();jdbc.update("insert into procedure_master(id,clinic_id,procedure_code,procedure_name) values (?,?,?,'Test procedure')",procedure,clinic,procedure.toString());jdbc.update("insert into procedure_price(clinic_id,procedure_id,price,effective_from) values (?,?,12.35,current_date)",clinic,procedure);var r=new CreateTreatmentPlanItemRequest();r.setClinicId(clinic);r.setProcedureId(procedure);return plans.addTreatmentPlanItem(plan,r);}
 UpdateTreatmentPlanItemRequest update(){var r=new UpdateTreatmentPlanItemRequest();r.setQuantity(3);r.setToothNumber(" 16 ");r.setClinicalNotes("Updated");return r;}
 RemoveTreatmentPlanItemRequest reason(String s){var r=new RemoveTreatmentPlanItemRequest();r.setReason(s);return r;}
 @Test void editRemoveAndTotals(){var p=plan();var i=item(p.getId());var edited=entries.update(p.getId(),i.getId(),clinic,"\"0\"",update());assertEquals(1,edited.getVersion());assertEquals(new BigDecimal("37.05"),edited.getFinalAmount());assertEquals(i.getUnitPrice(),edited.getUnitPrice());assertEquals("16",edited.getToothNumber());entries.remove(p.getId(),i.getId(),clinic,"\"1\"",reason("Correction"));assertTrue(plans.getTreatmentPlanItems(p.getId(),clinic).isEmpty());assertEquals(new BigDecimal("0.00"),plans.getTreatmentPlan(p.getId(),clinic).getFinalAmount());assertEquals(3,entries.history(p.getId(),clinic,0,20).totalElements());var status=new UpdateTreatmentPlanStatusRequest();status.setClinicId(clinic);status.setStatus(TreatmentPlanStatus.PRESENTED);assertThrows(IllegalArgumentException.class,()->plans.updateTreatmentPlanStatus(p.getId(),status));assertEquals(409,assertThrows(TreatmentItemException.class,()->entries.remove(p.getId(),i.getId(),clinic,"\"2\"",reason("Again"))).status);}
 @Test void versionsAndLifecycle(){var p=plan();var i=item(p.getId());assertEquals(428,assertThrows(TreatmentItemException.class,()->entries.update(p.getId(),i.getId(),clinic,null,update())).status);assertEquals(400,assertThrows(TreatmentItemException.class,()->entries.update(p.getId(),i.getId(),clinic,"0",update())).status);assertEquals(412,assertThrows(TreatmentItemException.class,()->entries.update(p.getId(),i.getId(),clinic,"\"5\"",update())).status);jdbc.update("update treatment_plan set status='PRESENTED' where id=?",p.getId());assertEquals(409,assertThrows(TreatmentItemException.class,()->entries.update(p.getId(),i.getId(),clinic,"\"0\"",update())).status);}
 @Test void historyGrantsAndIsolation(){var p=plan();item(p.getId());for(String role:List.of("SUPER_ADMIN","ADMIN","DOCTOR","RECEPTIONIST","ATTENDER")){var permissions=jdbc.queryForList("select p.permission_code from role_permission rp join role r on r.id=rp.role_id join permission p on p.id=rp.permission_id where r.role_code=? and r.clinic_id is null",String.class,role);login(permissions.toArray(String[]::new));if(List.of("RECEPTIONIST","ATTENDER").contains(role))assertThrows(AccessDeniedException.class,()->controller.history(p.getId(),clinic,0,20));else assertEquals(1,controller.history(p.getId(),clinic,0,20).totalElements());}login("TREATMENT_PLAN_VIEW");assertThrows(AccessDeniedException.class,()->controller.update(p.getId(),UUID.randomUUID(),clinic,"\"0\"",update()));UUID other=UUID.randomUUID();jdbc.update("insert into clinic(id,clinic_code,clinic_name) values (?,?,?)",other,other.toString(),"Other");actor=AppUser.builder().id(user).clinic(Clinic.builder().id(other).active(true).build()).build();login("TREATMENT_PLAN_HISTORY_VIEW","TREATMENT_PLAN_EDIT");assertEquals(404,assertThrows(TreatmentItemException.class,()->controller.history(p.getId(),clinic,0,20)).status);assertEquals(404,assertThrows(TreatmentItemException.class,()->controller.update(p.getId(),UUID.randomUUID(),clinic,"\"0\"",update())).status);}
 @Test void wrongParentAndLegacyDiscount(){var p=plan();var i=item(p.getId());var other=plan();assertEquals(404,assertThrows(TreatmentItemException.class,()->entries.update(other.getId(),i.getId(),clinic,"\"0\"",update())).status);jdbc.update("update treatment_plan_item set discount_value=1,discount_amount=1,final_amount=11.35 where id=?",i.getId());assertEquals(409,assertThrows(TreatmentItemException.class,()->entries.update(p.getId(),i.getId(),clinic,"\"0\"",update())).status);var r=update();r.setQuantity(1);assertEquals(new BigDecimal("11.35"),entries.update(p.getId(),i.getId(),clinic,"\"0\"",r).getFinalAmount());}
 @Test void auditImmutableAndRollback(){var p=plan();var i=item(p.getId());assertThrows(Exception.class,()->jdbc.update("delete from treatment_plan_item where id=?",i.getId()));assertThrows(Exception.class,()->jdbc.update("update treatment_plan_item_audit set operation='REMOVE' where item_id=?",i.getId()));assertThrows(Exception.class,()->jdbc.update("delete from treatment_plan_item_audit where item_id=?",i.getId()));assertThrows(Exception.class,()->new TransactionTemplate(transactions).executeWithoutResult(tx->{entries.update(p.getId(),i.getId(),clinic,"\"0\"",update());throw new IllegalStateException("Rollback");}));assertEquals(0,plans.getTreatmentPlanItems(p.getId(),clinic).get(0).getVersion());assertEquals(1,entries.history(p.getId(),clinic,0,20).totalElements());}
 @Test void unicodeReasonAndPagination(){var p=plan();String unicode="\u0c24\u0c2a\u0c4d\u0c2a\u0c41 \u0917\u0932\u0924";var i=item(p.getId());entries.remove(p.getId(),i.getId(),clinic,"\"0\"",reason(unicode));assertEquals(unicode,entries.history(p.getId(),clinic,0,1).content().get(0).removalReason());assertEquals(2,entries.history(p.getId(),clinic,0,1).totalPages());assertEquals(100,entries.history(p.getId(),clinic,0,500).size());}
 void race(Runnable first,Runnable second,int expectedStatus) throws Exception {
 var pool=Executors.newFixedThreadPool(2);var changed=new CountDownLatch(1);var release=new CountDownLatch(1);var entered=new CountDownLatch(1);
 try{var a=pool.submit(()->{login();try{new TransactionTemplate(transactions).executeWithoutResult(tx->{first.run();changed.countDown();try{if(!release.await(10,TimeUnit.SECONDS))throw new IllegalStateException("release timeout");}catch(InterruptedException e){throw new RuntimeException(e);}});}finally{SecurityContextHolder.clearContext();}});
 assertTrue(changed.await(10,TimeUnit.SECONDS));var b=pool.submit(()->{login();entered.countDown();try{second.run();return 0;}catch(TreatmentItemException e){return e.status;}catch(IllegalArgumentException e){return 400;}finally{SecurityContextHolder.clearContext();}});assertTrue(entered.await(10,TimeUnit.SECONDS));assertThrows(TimeoutException.class,()->b.get(200,TimeUnit.MILLISECONDS));release.countDown();a.get(10,TimeUnit.SECONDS);assertEquals(expectedStatus,b.get(10,TimeUnit.SECONDS));
 }finally{release.countDown();pool.shutdownNow();}}

 @Test void concurrentEdits() throws Exception {var p=plan();var i=item(p.getId());race(()->entries.update(p.getId(),i.getId(),clinic,"\"0\"",update()),()->entries.update(p.getId(),i.getId(),clinic,"\"0\"",update()),412);}
 @Test void concurrentRemoveAndPresentation() throws Exception {var p=plan();var i=item(p.getId());var r=new UpdateTreatmentPlanStatusRequest();r.setClinicId(clinic);r.setStatus(TreatmentPlanStatus.PRESENTED);race(()->entries.remove(p.getId(),i.getId(),clinic,"\"0\"",reason("Correction")),()->plans.updateTreatmentPlanStatus(p.getId(),r),400);}
 @Test void concurrentEditAndAdd() throws Exception {var p=plan();var i=item(p.getId());race(()->entries.update(p.getId(),i.getId(),clinic,"\"0\"",update()),()->item(p.getId()),0);assertEquals(new BigDecimal("49.40"),plans.getTreatmentPlan(p.getId(),clinic).getFinalAmount());}

 @Test void downstreamReferencesBlockBothMutations(){var p=plan();var i=item(p.getId());jdbc.update("insert into patient_follow_up(clinic_id,patient_id,treatment_plan_item_id,scheduled_date) values (?,?,?,current_date)",clinic,patient,i.getId());assertEquals(409,assertThrows(TreatmentItemException.class,()->entries.update(p.getId(),i.getId(),clinic,"\"0\"",update())).status);assertEquals(409,assertThrows(TreatmentItemException.class,()->entries.remove(p.getId(),i.getId(),clinic,"\"0\"",reason("Correction"))).status);}
 @Test void platformContextAndMutationPermissions(){var p=plan();var i=item(p.getId());login("TREATMENT_PLAN_VIEW");assertThrows(AccessDeniedException.class,()->controller.remove(p.getId(),i.getId(),clinic,"\"0\"",reason("Correction")));actor=AppUser.builder().id(user).build();login("TREATMENT_PLAN_HISTORY_VIEW");assertThrows(IllegalArgumentException.class,()->controller.history(p.getId(),null,0,20));assertEquals(1,controller.history(p.getId(),clinic,0,20).totalElements());assertEquals(404,assertThrows(TreatmentItemException.class,()->entries.update(p.getId(),UUID.randomUUID(),clinic,"\"0\"",update())).status);}
 @Test void auditFailureRollsBackItemAndTotals(){var p=plan();var i=item(p.getId());String function="reject_audit_"+i.getId().toString().replace("-","");jdbc.execute("create function "+function+"() returns trigger language plpgsql as $$ begin if NEW.item_id='"+i.getId()+"' then raise exception 'test audit failure'; end if; return NEW; end $$");jdbc.execute("create trigger "+function+" before insert on treatment_plan_item_audit for each row execute function "+function+"()");try{assertThrows(Exception.class,()->entries.update(p.getId(),i.getId(),clinic,"\"0\"",update()));assertEquals(0,plans.getTreatmentPlanItems(p.getId(),clinic).get(0).getVersion());assertEquals(new BigDecimal("12.35"),plans.getTreatmentPlan(p.getId(),clinic).getFinalAmount());assertEquals(1,entries.history(p.getId(),clinic,0,20).totalElements());}finally{jdbc.execute("drop trigger "+function+" on treatment_plan_item_audit");jdbc.execute("drop function "+function+"()");}}
 @Test void snapshotsAndReplacementPreserveSavedPrice(){var p=plan();var i=item(p.getId());jdbc.update("update procedure_price set price=99 where procedure_id=?",i.getProcedureId());var r=update();r.setDescription("  ");var changed=entries.update(p.getId(),i.getId(),clinic,"\"0\"",r);assertNull(changed.getDescription());assertEquals(new BigDecimal("37.05"),changed.getGrossAmount());var event=entries.history(p.getId(),clinic,0,20).content().get(0);assertEquals("UPDATE",event.operation());assertEquals(1,((Number)event.before().get("quantity")).intValue());assertEquals(3,((Number)event.after().get("quantity")).intValue());assertEquals(user,event.actorId());}
 @Test void concurrentPresentationThenEdit() throws Exception {var p=plan();var i=item(p.getId());var r=new UpdateTreatmentPlanStatusRequest();r.setClinicId(clinic);r.setStatus(TreatmentPlanStatus.PRESENTED);race(()->plans.updateTreatmentPlanStatus(p.getId(),r),()->entries.update(p.getId(),i.getId(),clinic,"\"0\"",update()),409);}
 @Test void concurrentRemoveThenEdit() throws Exception {var p=plan();var i=item(p.getId());race(()->entries.remove(p.getId(),i.getId(),clinic,"\"0\"",reason("Correction")),()->entries.update(p.getId(),i.getId(),clinic,"\"0\"",update()),409);}
 @Test void concurrentDiscountAndEdit() throws Exception {var p=plan();var i=item(p.getId());var r=new UpdateTreatmentPlanRequest();r.setClinicId(clinic);r.setDiscountType(DiscountType.PERCENTAGE);r.setDiscountValue(new BigDecimal("10"));race(()->plans.updateTreatmentPlan(p.getId(),r),()->entries.update(p.getId(),i.getId(),clinic,"\"0\"",update()),0);assertEquals(new BigDecimal("33.34"),plans.getTreatmentPlan(p.getId(),clinic).getFinalAmount());}
}
